"""Run the five TalkToTableau golden questions through the real E2E workflow."""
from __future__ import annotations

import json
import sys
import time
from pathlib import Path

from orchestration.workflow import TalkToTableauWorkflow
from routing.complexity import infer_routing_request
from routing.router import AdaptiveRouter

PROJECT_ROOT = Path(__file__).resolve().parent
DATA_FILE = PROJECT_ROOT / "database" / "golden_sales.csv"

GOLDEN_QUESTIONS = [
    "What is the total revenue from all sales?",
    "What is the total revenue generated by each region?",
    ("For each product, calculate the total revenue, total quantity sold, "
     "and profit, and identify which product generated the highest profit."),
    ("Which regions have a profit margin above the overall average profit "
     "margin, and what are their total revenue and total quantity sold?"),
    ("Analyze the sales data by year and region to determine which region "
     "shows the strongest improvement in profitability from 2024 to 2025. "
     "Compare its revenue, cost, profit, quantity sold, and profit margin "
     "across the two years, and explain the main factors contributing to "
     "the change."),
]

def dump(value):
    return value.model_dump() if hasattr(value, "model_dump") else value

def trace_events(trace):
    if trace is None:
        return []
    events = getattr(trace, "events", trace.get("events", []) if isinstance(trace, dict) else [])
    return [e.model_dump() if hasattr(e, "model_dump") else e for e in events]

def find_routing(events, text):
    for event in events:
        if text.lower() in str(event.get("message", "")).lower():
            m = event.get("metadata") or {}
            return {"tier": m.get("tier"), "reason": m.get("reason"),
                    "complexity_score": m.get("complexity_score")}
    return None

def find_execution(events, text):
    for event in events:
        if text.lower() in str(event.get("message", "")).lower():
            return event.get("metadata") or {}
    return None

def main():
    if not DATA_FILE.exists():
        raise FileNotFoundError(f"Golden dataset not found: {DATA_FILE}")

    router = AdaptiveRouter()
    workflow = TalkToTableauWorkflow(data_file=DATA_FILE)
    reports = []

    print("=" * 72)
    print("TalkToTableau — Golden 5 E2E Evaluation")
    print("=" * 72)
    print(f"Dataset: {DATA_FILE}\n")

    for number, question in enumerate(GOLDEN_QUESTIONS, 1):
        print("=" * 72)
        print(f"QUESTION {number}")
        print("=" * 72)
        print(question)

        inferred = infer_routing_request(user_request=question, schema_size=9)
        predicted = router.route(inferred)

        print("\nANALYZER")
        print("-" * 72)
        print(f"SQL complexity     : {inferred.sql_complexity}")
        print(f"Ambiguity          : {inferred.ambiguity}")
        print(f"Reasoning required : {inferred.reasoning_required}")
        print(f"Output complexity  : {inferred.output_complexity}")
        print(f"Predicted score    : {predicted.complexity_score}")
        print(f"Predicted tier     : {predicted.tier.value}")

        started = time.perf_counter()
        try:
            context = workflow.run(question)
            elapsed = time.perf_counter() - started
            events = trace_events(workflow.last_trace)

            ba = find_routing(events, "Model routed for Business Analyst")
            sql = find_routing(events, "Model routed for SQL generation")
            a2 = find_routing(events, "Model routed for Insight Verification")
            a3 = find_routing(events, "Model routed for Data Storytelling")

            report = {
                "question_number": number,
                "question": question,
                "status": "completed",
                "duration_seconds": round(elapsed, 3),
                "inferred_routing": dump(inferred),
                "predicted_routing": dump(predicted),
                "workflow_routing": {
                    "business_analyst": ba,
                    "sql_generation": sql,
                    "insight_verification": a2,
                    "data_storytelling": a3,
                },
                "model_executions": {
                    "business_analyst": find_execution(
                        events, "Business Analyst model execution completed"
                    ),
                    "sql_generation": find_execution(
                        events, "SQL generation model execution completed"
                    ),
                    "insight_verification": find_execution(
                        events, "Insight Verification model execution completed"
                    ),
                    "data_storytelling": find_execution(
                        events, "Data Storyteller model execution completed"
                    ),
                },
                "analytical_plan": dump(context.analytical_plan),
                "generated_sql": context.generated_sql,
                "sql_result": dump(context.sql_result),
                "insights": dump(context.insights),
                "visualization": dump(context.visualization),
                "story": dump(context.story),
            }

            print("\nRESULT")
            print("-" * 72)
            print(f"Actual BA tier     : {ba and ba.get('tier')}")
            print(f"Actual SQL tier    : {sql and sql.get('tier')}")
            print(f"Actual Agent 2 tier: {a2 and a2.get('tier')}")
            print(f"Actual Agent 3 tier: {a3 and a3.get('tier')}")
            print(f"Duration           : {elapsed:.2f}s")
            print("\nGenerated SQL:")
            print(context.generated_sql)
        except Exception as exc:
            elapsed = time.perf_counter() - started
            report = {
                "question_number": number,
                "question": question,
                "status": "failed",
                "duration_seconds": round(elapsed, 3),
                "inferred_routing": dump(inferred),
                "predicted_routing": dump(predicted),
                "error_type": type(exc).__name__,
                "error": str(exc),
                "trace_events": trace_events(workflow.last_trace),
            }
            print("\nFAILED")
            print("-" * 72)
            print(f"{type(exc).__name__}: {exc}")

        reports.append(report)

    output_file = PROJECT_ROOT / "golden5_e2e_report.json"
    output_file.write_text(json.dumps(reports, indent=2, default=str), encoding="utf-8")

    completed = sum(r["status"] == "completed" for r in reports)
    print("\n" + "=" * 72)
    print("GOLDEN 5 SUMMARY")
    print("=" * 72)
    print(f"Completed: {completed}/{len(reports)}")
    print(f"Failed   : {len(reports) - completed}/{len(reports)}")
    print(f"Report   : {output_file}")

    if completed != len(reports):
        sys.exit(1)

if __name__ == "__main__":
    main()
